def close(got: List[float], exp: List[float], rtol: float, atol: float = 0.0) -> bool:
    if len(got) != len(exp):
        print("len mismatch", len(got), len(exp))
        return False
    for i in range(len(got)):
        d = got[i] - exp[i]
        if d < 0: d = -d
        ae = exp[i] if exp[i] >= 0 else -exp[i]
        if d > atol + rtol * ae:
            print("mismatch at", i, got[i], exp[i])
            return False
    return True

@test
def test_conv3d():
    torch.manual_seed(0)
    m = nn_Conv3d(2, 4, (3, 2, 3), stride=(1, 2, 1), padding=(1, 0, 2), dilation=(1, 1, 2), groups=2)
    assert close(m.weight.tolist(), w0, 0.0)
    assert close(m.bias.tolist(), b0, 0.0)
    m.double()
    x = (torch.arange(2 * 2 * 4 * 5 * 6, dtype=torch.float64).reshape(2, 2, 4, 5, 6) / 50.0).sin().requires_grad_()
    y = m(x)
    assert y.shape == yshape
    (y * y.detach().cos()).sum().backward()
    assert close(y.tolist(), y, 1e-12, 1e-14) if False else close(y.tolist(), y_exp, 1e-12, 1e-14)
    assert close(x.grad.tolist(), gx, 1e-12, 1e-14)
    assert close(m.weight.grad.tolist(), gw, 1e-12, 1e-13)
    assert close(m.bias.grad.tolist(), gb, 1e-12)
    torch.manual_seed(1)
    m2 = nn_Conv3d(3, 2, 3, padding="same", bias=False)
    x2 = torch.randn(1, 3, 4, 4, 5)
    assert close(m2(x2).tolist(), y2, 1e-5, 1e-6)

@test
def test_batchnorm3d():
    x = (torch.arange(2 * 2 * 4 * 5 * 6, dtype=torch.float64).reshape(2, 2, 4, 5, 6) / 50.0).sin()
    bn = nn.BatchNorm3d(2).double()
    xb = x * 3 + 1
    bn.train()
    assert close(bn(xb).tolist(), bn_train, 1e-12, 1e-14)
    assert close(bn.running_mean.tolist(), bn_rm, 1e-12)
    assert close(bn.running_var.tolist(), bn_rv, 1e-12)
    bn.eval()
    assert close(bn(xb).tolist(), bn_eval, 1e-12, 1e-14)

test_conv3d()
test_batchnorm3d()
